<?php
require dirname(__DIR__).'/_init.php';use App\Core\AccessControl;use App\Core\Database;use App\Core\CSRF;
AccessControl::require('checkin.manage');$db=Database::connection();$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){CSRF::verify();$q=$db->prepare("UPDATE appointments SET status='checked_in',checked_in_at=NOW() WHERE id=? AND status='booked' AND appointment_date=CURDATE()");$q->execute([(int)$_POST['id']]);if(!$q->rowCount())$err='Appointment not found, not scheduled for today, or already cancelled/checked in.';}
$rows=$db->query("SELECT a.id,a.appointment_time,a.status,p.patient_number,p.full_name,d.name doctor_name FROM appointments a JOIN patients p ON p.id=a.patient_id JOIN doctors d ON d.id=a.doctor_id WHERE a.appointment_date=CURDATE() ORDER BY a.appointment_time")->fetchAll();require dirname(__DIR__).'/_layout_top.php';?>
<h2>Today's check-in</h2><?php if($err):?><div class="alert alert-danger"><?=e($err)?></div><?php endif;?><div class="card p-3 table-responsive"><table class="table"><thead><tr><th>Time</th><th>Patient</th><th>Doctor</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['appointment_time'])?></td><td><?=e($r['patient_number'].' - '.$r['full_name'])?></td><td><?=e($r['doctor_name'])?></td><td><?=e($r['status'])?></td><td><?php if($r['status']==='booked'):?><form method="post"><?=CSRF::field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-success">Check in</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php require dirname(__DIR__).'/_layout_bottom.php';?>
